// Limpa o que veio do app antes de gravar.
// As listas do Airtable (Tipo, Exigencia, Status) recusam texto vazio,
// entao mando null nesses casos, que o Airtable entende como 'em branco'.
const b = $json.body || {};
const texto = (v) => String(v ?? '').trim();
const lista = (v) => texto(v) || null;

return [{
  json: {
    documento: texto(b.documento).replace(/\D/g, ''),
    razaoSocial: texto(b.razaoSocial),
    nomeFantasia: texto(b.nomeFantasia),
    tipo: lista(b.tipo),
    exigenciaFiscal: lista(b.exigenciaFiscal),
    emails: texto(b.emails),
    // Telefone que consta no CNPJ, nao o do financeiro.
    whatsappCnpj: texto(b.whatsappCnpj),
    administradora: texto(b.administradora),
    empresaSindicos: texto(b.empresaSindicos),
    status: lista(b.status) || 'Ativo',
    observacoes: texto(b.observacoes),
  },
}];

