// Transforma a lista de enderecos que veio do app em um item por endereco,
// cada um ja apontando para o cliente recem-criado.
const corpo = $('Recebe pedido do app').first().json.body || {};
const entidadeId = $('Cria no Airtable').first().json.id;

let recebidos = [];
try {
  recebidos = JSON.parse(corpo.locais || '[]');
} catch (erro) {
  // App antigo (sem o campo) ou texto quebrado: segue sem endereco nenhum,
  // que e melhor do que perder o cadastro inteiro.
  recebidos = [];
}
if (!Array.isArray(recebidos)) recebidos = [];

const texto = (v) => String(v ?? '').trim();
const limpos = recebidos
  .map((l) => ({
    nome: texto(l.nome),
    endereco: texto(l.endereco),
    bairroCidade: texto(l.bairroCidade),
    acesso: texto(l.acesso),
    status: texto(l.status) || 'Ativo',
  }))
  .filter((l) => l.nome || l.endereco || l.bairroCidade || l.acesso);

// Sem endereco nenhum ainda precisa sair um item, senao o fluxo morre aqui
// e o app fica esperando uma resposta que nunca chega.
if (limpos.length === 0) return [{ json: { temLocal: false } }];

return limpos.map((l) => ({
  json: {
    temLocal: true,
    entidadeId,
    // Nome_do_Local e o campo principal da tabela: em branco, o registro
    // aparece sem titulo na lista do Airtable.
    nome: l.nome || l.endereco || 'Local sem nome',
    endereco: l.endereco,
    bairroCidade: l.bairroCidade,
    acesso: l.acesso,
    status: l.status,
  },
}));

