// Transforma a lista de contatos do app em um item por contato, cada um
// ja apontando para o cliente recem-criado.
const corpo = $('Recebe pedido do app').first().json.body || {};
const entidadeId = $('Cria no Airtable').first().json.id;

let recebidos = [];
try {
  recebidos = JSON.parse(corpo.contatos || '[]');
} catch (erro) {
  // App antigo (sem o campo) ou texto quebrado: segue sem contato nenhum.
  recebidos = [];
}
if (!Array.isArray(recebidos)) recebidos = [];

const texto = (v) => String(v ?? '').trim();
const lista = (v) => (Array.isArray(v) ? v.map(texto).filter(Boolean) : []);

const limpos = recebidos
  .map((c) => ({
    nome: texto(c.nome),
    cargo: texto(c.cargo),
    whatsapps: lista(c.whatsapps),
    emails: lista(c.emails),
    observacoes: texto(c.observacoes),
    status: texto(c.status) || 'Ativo',
  }))
  .filter((c) => c.nome || c.whatsapps.length || c.emails.length || c.observacoes);

// Sem contato nenhum ainda precisa sair um item, senao o fluxo morre aqui
// e o app fica esperando uma resposta que nunca chega.
if (limpos.length === 0) return [{ json: { temContato: false } }];

return limpos.map((c) => ({
  json: {
    temContato: true,
    entidadeId,
    // Nome_Contato e o campo principal: em branco, o registro aparece sem
    // titulo na lista do Airtable.
    nome: c.nome || c.whatsapps[0] || c.emails[0] || 'Contato sem nome',
    // Lista de escolha recusa texto vazio; null e 'em branco' para o Airtable.
    cargo: c.cargo || null,
    // Um valor por linha: e assim que o campo guarda varios sem criar coluna.
    whatsapps: c.whatsapps.join('\n'),
    emails: c.emails.join('\n'),
    observacoes: c.observacoes,
    status: c.status,
  },
}));

